
const readline=require('node:readline');let loggedIn=false,n=0,threads=new Map(),turns=new Map(),tools=new Map();
const send=x=>process.stdout.write(JSON.stringify(x)+'\n'),reply=(id,result)=>send({id,result}),event=(method,params)=>send({method,params});
const finish=(t,text)=>{event('item/agentMessage/delta',{threadId:t.threadId,turnId:t.id,delta:text});event('item/completed',{threadId:t.threadId,turnId:t.id,item:{type:'agentMessage',text,phase:'final_answer'}});event('turn/completed',{threadId:t.threadId,turn:{id:t.id,status:'completed'}})};
readline.createInterface({input:process.stdin}).on('line',line=>{const m=JSON.parse(line),p=m.params||{};if(!m.method){const t=tools.get(m.id);if(t){tools.delete(m.id);if(!m.result?.success||!t.imagesReceived){event('turn/completed',{threadId:t.threadId,turn:{id:t.id,status:'failed'}});return}if(!t.rows){finish(t,'已读取语音原文和课件。');return}finish(t,JSON.stringify(t.rows.map(r=>({id:r.id,text:r.text.replace('牙油质','牙釉质'),uncertain:false,reason:'课件第 1 页支持'}))))}return}switch(m.method){
case 'initialize':reply(m.id,{userAgent:'fixture'});break;
case 'account/read':reply(m.id,{account:loggedIn?{type:'chatgpt',planType:'plus'}:null});break;
case 'account/login/start':loggedIn=true;reply(m.id,{type:'chatgpt',authUrl:'https://auth.openai.com/',loginId:'fixture'});break;
case 'model/list':reply(m.id,{data:process.env.LISTENING_ASSISTANT_DEEPSEEK_KEY?['deepseek-flash','deepseek-v4-pro'].map((model,index)=>({model,displayName:model,isDefault:!index,supportedReasoningEfforts:['low','high','max'].map(reasoningEffort=>({reasoningEffort})),defaultReasoningEffort:'low'})):[{model:'fixture-codex',displayName:'测试 Codex',isDefault:true,supportedReasoningEfforts:[{reasoningEffort:'low'},{reasoningEffort:'high'}],defaultReasoningEffort:'low'}]});break;
case 'thread/start':{if(process.env.LISTENING_ASSISTANT_DEEPSEEK_KEY){if(!process.argv.some(x=>x==='model_provider="deepseek"')||!p.model.startsWith('deepseek-'))throw Error('DeepSeek provider was not selected');if(process.argv.some(x=>x.includes(process.env.LISTENING_ASSISTANT_DEEPSEEK_KEY)))throw Error('Key leaked to process arguments')}const id='thread-'+(++n);threads.set(id,p);reply(m.id,{thread:{id}});break}
case 'turn/start':{if(p.sandboxPolicy?.access){send({id:m.id,error:{code:-32600,message:'Invalid request: readOnly.access is no longer supported'}});break}const t={id:'turn-'+(++n),threadId:p.threadId},text=p.input[0].text;t.imagesReceived=p.input.some(i=>i.type==='image'&&i.url.startsWith('data:image/'));turns.set(t.threadId,t);reply(m.id,{turn:{id:t.id,status:'inProgress'}});event('turn/started',{threadId:t.threadId,turn:{id:t.id}});if(text.includes('等待取消'))break;
if(threads.get(t.threadId).dynamicTools){if(text.includes('检查导入资料')){if(!threads.get(t.threadId).developerInstructions.includes('牙油质结构这个必考。'))throw Error('原文未传入')}else t.rows=JSON.parse(text.split('[用户]\n')[1].split('\n课件目录')[0]).rows;if(t.rows&&t.rows[0].text!=='牙油质结构这个必考。')throw Error('unexpected source');const id='tool-'+n;tools.set(id,t);send({id,method:'item/tool/call',params:{threadId:t.threadId,turnId:t.id,tool:'courseware_pages',turnId:t.id,arguments:{pages:[1]}}})}
else if(text.includes('"selfPractice"'))finish(t,JSON.stringify(Array.from({length:5},(_,i)=>({stem:'牙釉质结构自测题'+(i+1),type:'简答',topic:'牙釉质',reason:'本课字幕',answer:'模拟参考解析。',explanation:'模拟详细解析：结合本课字幕逐项说明。'}))));else if(text.includes('"subtitles"'))finish(t,JSON.stringify({keyPoints:[{level:'必考',topic:'牙釉质',detail:'掌握结构',quote:'牙釉质结构这个必考。',timestamp:'00:00:01'}],notTested:[],uncertain:[]}));else finish(t,'连接成功。');break}
case 'turn/steer':{const t=turns.get(p.threadId);if(t.id!==p.expectedTurnId||!p.input.some(i=>i.type==='image'&&i.url.startsWith('data:image/')))throw Error('图片附件未传入');t.imagesReceived=true;reply(m.id,{turnId:t.id});break}
case 'turn/interrupt':{const t=turns.get(p.threadId);reply(m.id,{});event('turn/completed',{threadId:t.threadId,turn:{id:t.id,status:'interrupted'}});break}
}});
